-- HALO: check that migration 0032 is applied correctly. Read only.
-- Generated by scripts/build-apply-bundle.mjs from each migration's own verification query.
-- Expect one row: all_migrations_ok = true and failing = none.

with checks as (
  select '0032' as migration, j.key as check_name, coalesce(j.value::boolean, false) as ok
  from (
    select
        (select bool_and(relrowsecurity) from pg_class
          where oid in ('public.participation_profiles'::regclass, 'public.participation_opportunities'::regclass))
          as rls_on,
        (select count(*) from pg_policies where schemaname = 'public'
          and tablename in ('participation_profiles', 'participation_opportunities')) = 0
          as no_policies,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           cross join unnest(array['public.participation_profiles', 'public.participation_opportunities']) as t
           where has_any_column_privilege(r, t, 'SELECT')
              or has_any_column_privilege(r, t, 'INSERT')
              or has_any_column_privilege(r, t, 'UPDATE')
              or has_table_privilege(r, t, 'DELETE'))
          as no_client_access,
        not exists (
          select 1 from unnest(array['anon', 'authenticated']) as r
           cross join unnest(array['public.read_participation_opportunities(text[], timestamptz)',
                                   'public.read_participation_opportunity(text, timestamptz)',
                                   'public.read_participation_profiles(text[], timestamptz)',
                                   'public.participation_opportunity_json(public.participation_opportunities)',
                                   'public.participation_profile_json(public.participation_profiles)',
                                   'public.participation_listing_guard()',
                                   'public.participation_opportunity_zone_check()',
                                   'public.participation_text_ok(text, integer)',
                                   'public.participation_url_ok(text)',
                                   'public.participation_list_ok(text[], integer, integer)',
                                   'public.participation_places_ok(text[])',
                                   'public.participation_steps_ok(jsonb)',
                                   'public.participation_sources_ok(jsonb)']) as f
           where has_function_privilege(r, f, 'EXECUTE'))
          and (select bool_and(has_function_privilege('service_role', f, 'EXECUTE'))
                 from unnest(array['public.read_participation_opportunities(text[], timestamptz)',
                                   'public.read_participation_opportunity(text, timestamptz)',
                                   'public.read_participation_profiles(text[], timestamptz)']) as f)
          as functions_service_role_only,
        (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
          where n.nspname = 'public' and not p.prosecdef and 'search_path=public' = any (p.proconfig)
            and p.proname in ('participation_text_ok', 'participation_url_ok', 'participation_list_ok',
                              'participation_places_ok', 'participation_steps_ok', 'participation_sources_ok',
                              'participation_listing_guard', 'participation_opportunity_zone_check',
                              'participation_opportunity_json', 'participation_profile_json',
                              'read_participation_opportunities', 'read_participation_opportunity',
                              'read_participation_profiles')) = 13
          as functions_invoker_pinned,
        (select count(*) from pg_trigger
          where tgname in ('participation_profiles_guard', 'participation_opportunities_guard', 'participation_opportunities_zone')
            and not tgisinternal) = 3
          as triggers_on,
        (select count(*) from pg_constraint
          where conrelid in ('public.participation_profiles'::regclass, 'public.participation_opportunities'::regclass)
            and contype = 'c') = 16
          as sixteen_checks
  ) q, jsonb_each_text(to_jsonb(q)) j
)
select bool_and(ok) as all_migrations_ok,
       count(*) as checks_run,
       coalesce(string_agg(migration || '.' || check_name, ', ') filter (where not ok), 'none') as failing
from checks;
